      "id": "translation-units-odr",
      "title": "ODR: почему заголовок проверяется не только внутри одного .cpp",
      "lead": "Компилятор обычно обрабатывает каждый .cpp отдельно. Правило одного определения связывает результаты этих отдельных компиляций в одну согласованную программу.",
      "blocks": [
        {
          "type": "text",
          "html": "После обработки include и макросов каждый .cpp вместе с включённым текстом образует единицу трансляции. Объявление сообщает имя и тип, а определение функции содержит её тело. Два .cpp могут видеть одно объявление из заголовка, а определение получить из третьего объектного файла при линковке."
        },
        {
          "type": "text",
          "html": "ODR (One Definition Rule, правило одного определения) регулирует, где допустимы повторные определения. Для вызываемой обычной функции с внешним связыванием требуется одно определение во всей программе. Если её тело положить в общий заголовок, включённый в два .cpp, оно попадёт в обе единицы трансляции. Include guard не объединит их: он работает только внутри отдельной обработки текста."
        },
        {
          "type": "code",
          "caption": "math.hpp: определение, допустимое в нескольких единицах трансляции",
          "code": "#ifndef LESSON_MATH_HPP\n#define LESSON_MATH_HPP\ninline int twice(int x) { return x * 2; }\n#endif"
        },
        {
          "type": "code",
          "caption": "left.cpp: первый потребитель заголовка",
          "code": "#include \"math.hpp\"\nint from_left() { return twice(21); }"
        },
        {
          "type": "code",
          "caption": "main.cpp: второй потребитель того же определения",
          "code": "#include \"math.hpp\"\n#include <iostream>\nint from_left();\nint main() {\n    std::cout << from_left() << ' ' << twice(3); // 42 6\n}"
        },
        {
          "type": "text",
          "html": "Inline здесь разрешает согласованные определения одной функции в нескольких единицах трансляции. Это не приказ встроить вызов и не обещание ускорения. Без inline два обычных определения twice нарушат правило; типичная диагностика линковщика — multiple definition. Другой корректный вариант: оставить объявление в math.hpp, а одно тело перенести в math.cpp и включить его в сборку."
        },
        {
          "type": "text",
          "html": "Для inline недостаточно одинакового имени. Требования включают одинаковую последовательность токенов определения и согласованное разрешение используемых имён, с оговорёнными стандартом исключениями. Если макрос в двух .cpp создаёт разные тела одной inline-функции, программа может нарушить ODR даже при успешной линковке. Выяснять последствия такого нарушения запуском небезопасно: единственный правильный вывод не задан."
        },
        {
          "type": "text",
          "html": "Классы и многие шаблонные определения также обычно размещают в заголовках при соблюдении требований ODR. Шаблонное тело нужно там, где создаётся нужная специализация. Явное инстанцирование позволяет вынести работу для заранее выбранных типов в отдельную единицу трансляции, но это уже осознанное ограничение поддерживаемого набора, а не способ спрятать любое шаблонное тело."
        },
        {
          "type": "text",
          "html": "Не заменяй inline на static механически. Функция с внутренним связыванием в каждом .cpp будет отдельной сущностью. Например, её локальная static-переменная станет отдельной для каждого такого определения. Для внешней inline-функции при соблюдении ODR это одна сущность с общим локальным static-состоянием."
        },
        {
          "type": "note",
          "kind": "key",
          "html": "Разбирай ошибку в два шага: сколько определений видит каждая единица трансляции и сколько допустимых определений образует вся программа. Успешная линковка не доказывает соблюдение всех случаев ODR."
        },
        {
          "type": "note",
          "kind": "tip",
          "html": "Правила и подробности: <a href=\"https://timsong-cpp.github.io/cppwp/n4861/basic.def.odr\" target=\"_blank\" rel=\"noreferrer\">C++20: правило одного определения</a>; <a href=\"https://timsong-cpp.github.io/cppwp/n4861/dcl.inline\" target=\"_blank\" rel=\"noreferrer\">C++20: inline</a>."
        }
      ],
      "substation": "build-pipeline"
