          "html": "Ты собрал приложение и перенёс его в другое Linux-окружение. Файл виден, разрешение на исполнение есть, а сообщения из main нет. Не стоит сразу искать ошибку бизнес-логики: до main должны согласоваться формат файла, архитектура процессора, путь загрузчика и зависимости. Компилятор и линковщик проверяли другую фазу — создание исполняемого файла. Эта история продолжает путь символа из предыдущего раздела, но теперь вопрос не «собралось ли», а «какой этап запуска действительно состоялся»."
