          "html": "<b>ELF</b> — формат исполняемых файлов, объектных файлов и библиотек на многих Linux-системах. В нём есть не только машинные инструкции, но и служебные описания. Поле Machine обозначает целевую архитектуру. Запись <code>PT_INTERP</code> в программных заголовках обычного динамического исполняемого ELF указывает путь интерпретатора — в данном контексте программы динамического загрузчика, а не Python или shell. Записи <code>DT_NEEDED</code> называют требуемые общие библиотеки. Ядро не обязано самостоятельно искать каждую такую библиотеку вместо загрузчика."
