              "title": "app есть, но execve сообщает ENOENT",
              "html": "Файл app доступен; readelf показывает PT_INTERP=/lesson/missing-loader; этого интерпретатора в текущем окружении нет. Может отсутствовать не сам app, а нужный для его запуска файл."
