          "type": "text",
          "html": "<strong>7. Не всякая похожая ошибка имеет ту же причину.</strong> Если в percent.cpp вместо int clamp_percent(int) определить int clamp_percent(int&amp;), это будет другая перегрузка, а не реализация обещанной функции. Даже присутствие percent.o в линковке тогда не найдёт нужный вариант int. Если же определить обычную функцию в заголовке без inline и включить его в оба .cpp, возможна диагностика нескольких определений. Поэтому проверяем не только имя файла, но и точную сигнатуру и число определений."
