          "type": "text",
          "html": "<strong>8. Что здесь проверено и чего нет.</strong> Полный проект можно собрать обоими путями; неверная линковка должна завершиться отказом. Это небольшой воспроизводимый сценарий, а не настройка промышленного CI, пакетирования или установки. Для задачи станции достаточно уметь проследить появление каждого артефакта и не пытаться чинить undefined reference изменением алгоритма. Перед практикой объясни, какую дополнительную информацию даёт отдельная успешная компиляция main.o."
